$dev='C:\Users\eric_rash\Desktop\DEV'
Get-ChildItem $dev -Directory | ForEach-Object {
  $g = Test-Path (Join-Path $_.FullName '.git')
  $n = (Get-ChildItem $_.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object).Count
  [PSCustomObject]@{Name=$_.Name; Git=$g; Files=$n; Modified=$_.LastWriteTime.ToString('yyyy-MM-dd')}
} | Sort-Object Name | Format-Table -AutoSize | Out-String -Width 200

$dev='C:\Users\eric_rash\Desktop\DEV'
Get-ChildItem $dev -Directory | Where-Object { Test-Path (Join-Path $_.FullName '.git') } | ForEach-Object {
  $p=$_.FullName
  $remote = (git -C $p remote get-url origin 2>$null)
  if(-not $remote){$remote='<NO REMOTE>'}
  $dirty = (git -C $p status --porcelain 2>$null | Measure-Object).Count
  $ahead = (git -C $p rev-list --count '@{u}..HEAD' 2>$null)
  if($null -eq $ahead -or $ahead -eq ''){$ahead='no-upstream'}
  [PSCustomObject]@{Name=$_.Name; Remote=$remote; Dirty=$dirty; Unpushed=$ahead}
} | Format-Table -AutoSize | Out-String -Width 250

$c="$env:USERPROFILE\.claude"
"=== ~/.claude top level ==="
Get-ChildItem $c -Force | ForEach-Object {
  $sz = if($_.PSIsContainer){ try{[math]::Round(((Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue)|Measure-Object Length -Sum).Sum/1MB,1)}catch{0} } else {[math]::Round($_.Length/1MB,2)}
  "{0,-32} {1,8} MB  {2}" -f $_.Name, $sz, $(if($_.PSIsContainer){'DIR'}else{'file'})
}
"`n=== git status of ~/.claude (if repo) ==="
if(Test-Path "$c\.git"){ git -C $c remote get-url origin 2>&1; (git -C $c status --porcelain 2>&1 | Measure-Object).Count } else { "NOT A GIT REPO" }
"`n=== global-memory ==="
if(Test-Path "$c\global-memory"){ Get-ChildItem "$c\global-memory" -Force | Select-Object Name,Length | Format-Table -AutoSize | Out-String } else {"missing"}

function RepoState($path,$label){
  if(-not(Test-Path $path)){ "{0,-24} MISSING" -f $label; return }
  if(-not(Test-Path "$path\.git")){ "{0,-24} EXISTS but NOT A GIT REPO" -f $label; return }
  $r=(git -C $path remote get-url origin 2>$null); if(-not $r){$r='<no remote>'}
  $d=(git -C $path status --porcelain 2>$null|Measure-Object).Count
  $a=(git -C $path rev-list --count '@{u}..HEAD' 2>$null); if(!$a){$a='no-upstream'}
  $last=(git -C $path log -1 --format='%cd' --date=short 2>$null)
  "{0,-24} {1,-58} dirty={2} unpushed={3} last={4}" -f $label,$r,$d,$a,$last
}
$U=$env:USERPROFILE
RepoState "$U\.claude\skills" "skills"
RepoState "$U\.claude\global-memory" "global-memory"
RepoState "$U\.claude\claude-memory-compiler" "memory-compiler"
RepoState "$U\Desktop\SecondBrain" "SecondBrain"
RepoState "$U\.codex" "codex"
"`n=== Google Drive mount ==="
Get-PSDrive -PSProvider FileSystem | Select-Object Name,Root | Format-Table -AutoSize | Out-String
if(Test-Path 'G:\My Drive\Backups'){ "G: Backups tree:"; Get-ChildItem 'G:\My Drive\Backups' -Recurse -Depth 1 | Select-Object FullName,LastWriteTime | Format-Table -AutoSize | Out-String -Width 160 } else { "G:\My Drive\Backups NOT FOUND" }

"=== OneDrive roots ==="
Get-ChildItem $env:USERPROFILE -Directory -Filter 'OneDrive*' | Select-Object -ExpandProperty FullName
"`n=== DEV-NonRepo backup ==="
$od = Get-ChildItem $env:USERPROFILE -Directory -Filter 'OneDrive*' | Select-Object -First 1 -ExpandProperty FullName
$nr = Join-Path $od 'Backups\DEV-NonRepo'
if(Test-Path $nr){
  "Path: $nr"
  $items = Get-ChildItem $nr -Directory
  "Folders backed up: $($items.Count)"
  $items | Select-Object Name,LastWriteTime | Sort-Object Name | Format-Table -AutoSize | Out-String -Width 120
} else { "NOT FOUND at $nr"; if(Test-Path (Join-Path $od 'Backups')){ Get-ChildItem (Join-Path $od 'Backups') | Select-Object Name,LastWriteTime | Format-Table -AutoSize | Out-String } }
"`n=== Scheduled tasks ==="
Get-ScheduledTask | Where-Object {$_.TaskName -match 'Keystone|Morning|Briefing|Backup|StackDoctor|Agy'} | ForEach-Object {
  $i = $_ | Get-ScheduledTaskInfo
  [PSCustomObject]@{Task=$_.TaskName; State=$_.State; Last=$i.LastRunTime; Result=$i.LastTaskResult; Next=$i.NextRunTime}
} | Format-Table -AutoSize | Out-String -Width 160

$b = "$env:USERPROFILE\OneDrive - Baylor University"
"=== Baylor OneDrive\Backups ==="
if(Test-Path "$b\Backups"){
  Get-ChildItem "$b\Backups" | Select-Object Name,LastWriteTime | Format-Table -AutoSize | Out-String
  if(Test-Path "$b\Backups\DEV-NonRepo"){
    $f = Get-ChildItem "$b\Backups\DEV-NonRepo" -Directory
    "DEV-NonRepo folders: $($f.Count)"
    $f | Select-Object Name,LastWriteTime | Sort-Object Name | Format-Table -AutoSize | Out-String -Width 120
  } else { "!! DEV-NonRepo NOT PRESENT under Baylor Backups" }
} else { "!! No Backups folder in Baylor OneDrive"; Get-ChildItem $b -Directory | Select-Object -ExpandProperty Name }
"`n=== daily-backup.ps1 log (tail) ==="
$logs = Get-ChildItem "$env:USERPROFILE\.claude\scripts\logs" -Filter '*backup*' -EA SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if($logs){ "Log: $($logs.FullName)  ($($logs.LastWriteTime))"; Get-Content $logs.FullName -Tail 40 } else { "no backup log found"; Get-ChildItem "$env:USERPROFILE\.claude\scripts\logs" -EA SilentlyContinue | Select-Object Name,LastWriteTime | Format-Table -AutoSize | Out-String }

$dev='C:\Users\eric_rash\Desktop\DEV'
$nonrepo = Get-ChildItem $dev -Directory | Where-Object { -not (Test-Path (Join-Path $_.FullName '.git')) }
"=== size per non-repo folder (top 12) ==="
$nonrepo | ForEach-Object {
  $s = ((Get-ChildItem $_.FullName -Recurse -File -EA SilentlyContinue)|Measure-Object Length -Sum).Sum
  [PSCustomObject]@{Folder=$_.Name; MB=[math]::Round($s/1MB,1)}
} | Sort-Object MB -Descending | Select-Object -First 12 | Format-Table -AutoSize | Out-String
"=== files over 100MB (GitHub hard limit) ==="
$big = Get-ChildItem $dev -Recurse -File -EA SilentlyContinue | Where-Object { $_.Length -gt 100MB }
if($big){ $big | ForEach-Object { "{0,8} MB  {1}" -f [math]::Round($_.Length/1MB,0), $_.FullName.Replace($dev,'') } } else { "none" }
"=== files 50-100MB (GitHub warns) ==="
(Get-ChildItem $dev -Recurse -File -EA SilentlyContinue | Where-Object { $_.Length -gt 50MB -and $_.Length -le 100MB } | Measure-Object).Count

$dev='C:\Users\eric_rash\Desktop\DEV'
$skip='\\node_modules\\|\\\.venv\\|\\__pycache__\\|\\\.git\\|\\\.next\\|\\venv\\|\\dist\\|\\\.pytest_cache\\'
$rows = Get-ChildItem $dev -Directory | Where-Object { Test-Path (Join-Path $_.FullName '.git') } | ForEach-Object {
  $p=$_.FullName
  $tracked = New-Object System.Collections.Generic.HashSet[string]
  (git -C $p ls-files 2>$null) | ForEach-Object { [void]$tracked.Add((Join-Path $p ($_ -replace '/','\')).ToLower()) }
  $orphan=0; $ocount=0
  Get-ChildItem $p -Recurse -File -EA SilentlyContinue | Where-Object { $_.FullName -notmatch $skip } | ForEach-Object {
    if(-not $tracked.Contains($_.FullName.ToLower())){ $orphan += $_.Length; $ocount++ }
  }
  [PSCustomObject]@{Repo=$_.Name; OrphanMB=[math]::Round($orphan/1MB,1); Files=$ocount}
}
$rows | Sort-Object OrphanMB -Descending | Format-Table -AutoSize | Out-String
"TOTAL UNBACKED INSIDE GIT REPOS: {0} GB across {1} files" -f [math]::Round((($rows|Measure-Object OrphanMB -Sum).Sum/1024),2), ($rows|Measure-Object Files -Sum).Sum

"=== D: drive ==="
$d = Get-PSDrive -Name D -EA SilentlyContinue
if($d){ "Free: {0} GB   Used: {1} GB   Total: {2} GB" -f [math]::Round($d.Free/1GB,1), [math]::Round($d.Used/1GB,1), [math]::Round(($d.Free+$d.Used)/1GB,1) } else { "D: NOT MOUNTED" }
try { $v = Get-Volume -DriveLetter D -EA Stop; "Label: '$($v.FileSystemLabel)'  FS: $($v.FileSystem)  Type: $($v.DriveType)" } catch { "volume info unavailable" }
"`n=== D:\AssistantBackup ==="
if(Test-Path 'D:\AssistantBackup'){
  $n=(Get-ChildItem 'D:\AssistantBackup' -Recurse -File -EA SilentlyContinue|Measure-Object).Count
  "EXISTS - $n files"
  Get-ChildItem 'D:\AssistantBackup' | Select-Object Name,LastWriteTime | Format-Table -AutoSize | Out-String
} else { "does not exist yet - will be created" }
"`n=== D: root contents ==="
Get-ChildItem 'D:\' -Force -EA SilentlyContinue | Select-Object Name,LastWriteTime | Format-Table -AutoSize | Out-String

$e="$env:USERPROFILE\.claude\global-memory\transcripts\.errors.log"
if(Test-Path $e){
  $len=(Get-Item $e).Length
  if($len -gt 0){ "NON-EMPTY ($len bytes) - last 15 lines:"; Get-Content $e -Tail 15 } else { "empty - no hook failures" }
} else { "no .errors.log present" }

