# Phase 1 Rescue — 2026-08-03
# Spec: KeystoneOS/docs/superpowers/specs/2026-08-03-machine-migration-and-backup-contract-design.md
# Copies at-risk data to the external SSD. Read-only against sources.

$ErrorActionPreference = 'Continue'
$dest = 'D:\AssistantBackup'
$dev  = 'C:\Users\eric_rash\Desktop\DEV'
$U    = $env:USERPROFILE
$man  = Join-Path $dest 'MANIFEST'
$log  = Join-Path $man 'rescue.log'

New-Item -ItemType Directory -Force -Path $man | Out-Null
function Log($m){ $line = "{0} {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $m; $line; Add-Content -Path $log -Value $line }

# Rebuildable directories excluded per spec "Out of scope"
$XD = @('node_modules','.venv','venv','__pycache__','.next','dist','.pytest_cache','.turbo','.parcel-cache')

Log "===== phase1-rescue start ====="
Log "dest=$dest  free=$([math]::Round((Get-PSDrive D).Free/1GB,1))GB"

$class = New-Object System.Collections.Generic.List[object]

# ---------- 1. Non-repo DEV folders ----------
$nonrepo = Get-ChildItem $dev -Directory | Where-Object { -not (Test-Path (Join-Path $_.FullName '.git')) }
Log "STAGE 1: $($nonrepo.Count) non-repo folders"
foreach($f in $nonrepo){
  $to = Join-Path $dest "DEV-nonrepo\$($f.Name)"
  $args = @($f.FullName, $to, '/E', '/R:1', '/W:1', '/NFL', '/NDL', '/NP', '/NJH', '/NJS', '/XD') + $XD
  $null = & robocopy @args
  $rc = $LASTEXITCODE
  $ok = if($rc -lt 8){'OK'}else{'FAIL'}
  Log "  NONREPO $($f.Name) : $ok (rc=$rc)"
  $class.Add([PSCustomObject]@{ path="DEV-nonrepo\$($f.Name)"; source=$f.FullName; kind='non-repo'; result=$ok })
}

# ---------- 2. Orphaned files inside git repos (the structural hole) ----------
$repos = Get-ChildItem $dev -Directory | Where-Object { Test-Path (Join-Path $_.FullName '.git') }
Log "STAGE 2: orphaned (untracked+ignored) files across $($repos.Count) repos"
$skipRe = '(^|\\)(node_modules|\.venv|venv|__pycache__|\.next|dist|\.pytest_cache|\.turbo|\.parcel-cache)(\\|$)'
foreach($r in $repos){
  $p = $r.FullName
  $orphans = @()
  $orphans += (git -C $p ls-files --others --exclude-standard 2>$null)
  $orphans += (git -C $p ls-files --others --ignored --exclude-standard 2>$null)
  $orphans = $orphans | Where-Object { $_ } | Sort-Object -Unique
  $n=0; $bytes=0
  foreach($rel in $orphans){
    $relWin = $rel -replace '/','\'
    if($relWin -match $skipRe){ continue }
    $src = Join-Path $p $relWin
    if(-not (Test-Path -LiteralPath $src -PathType Leaf)){ continue }
    $dst = Join-Path $dest "DEV-repo-data\$($r.Name)\$relWin"
    $dstDir = Split-Path $dst -Parent
    if(-not (Test-Path -LiteralPath $dstDir)){ New-Item -ItemType Directory -Force -Path $dstDir | Out-Null }
    try { Copy-Item -LiteralPath $src -Destination $dst -Force -EA Stop; $n++; $bytes += (Get-Item -LiteralPath $src).Length }
    catch { Log "    ERR copy $src : $($_.Exception.Message)" }
  }
  if($n -gt 0){
    Log "  ORPHAN $($r.Name) : $n files, $([math]::Round($bytes/1MB,1)) MB"
    $class.Add([PSCustomObject]@{ path="DEV-repo-data\$($r.Name)"; source=$p; kind='repo-orphan'; result="$n files" })
  }
}

# ---------- 3. Claude / Codex / Gemini state ----------
Log "STAGE 3: AI state"
$state = @(
  @{ from="$U\.claude\projects";               to="$dest\claude\projects";   xd=@() },
  @{ from="$U\.claude\global-memory";          to="$dest\claude\global-memory"; xd=@() },
  @{ from="$U\.claude\skills";                 to="$dest\claude\skills";     xd=@('node_modules') },
  @{ from="$U\.claude\agents";                 to="$dest\claude\agents";     xd=@() },
  @{ from="$U\.claude\hooks";                  to="$dest\claude\hooks";      xd=@() },
  @{ from="$U\.claude\scripts";                to="$dest\claude\scripts";    xd=@() },
  @{ from="$U\.claude\claude-memory-compiler"; to="$dest\claude\claude-memory-compiler"; xd=@('node_modules','.venv','__pycache__') },
  @{ from="$U\.codex";                         to="$dest\codex";             xd=@('work','node_modules') },
  @{ from="$U\.gemini";                        to="$dest\gemini";            xd=@('node_modules') }
)
foreach($s in $state){
  if(-not (Test-Path $s.from)){ Log "  SKIP $($s.from) (absent)"; continue }
  $a = @($s.from, $s.to, '/E','/R:1','/W:1','/NFL','/NDL','/NP','/NJH','/NJS')
  if($s.xd.Count){ $a += '/XD'; $a += $s.xd }
  $null = & robocopy @a
  $rc = $LASTEXITCODE
  Log "  STATE $(Split-Path $s.from -Leaf) : $(if($rc -lt 8){'OK'}else{'FAIL'}) (rc=$rc)"
}

# Loose config files at ~/.claude root (excludes .credentials.json by design)
$cfgTo = "$dest\claude\config"
New-Item -ItemType Directory -Force -Path $cfgTo | Out-Null
foreach($f in 'settings.json','settings.local.json','keybindings.json','CLAUDE.md','RESTORE.md','package.json','statusline-command.py','.gitignore'){
  $src = "$U\.claude\$f"
  if(Test-Path $src){ Copy-Item $src $cfgTo -Force }
}
Copy-Item "$U\.claude\RESTORE.md" "$dest\RESTORE.md" -Force -EA SilentlyContinue
Log "  STATE config files + RESTORE.md at SSD root : OK"

# ---------- 4. Fresh clones of all GitHub repos ----------
Log "STAGE 4: cloning GitHub repos (self-sufficient SSD copy)"
$cloneDir = Join-Path $dest 'repos'
New-Item -ItemType Directory -Force -Path $cloneDir | Out-Null
$remotes = @{}
foreach($r in $repos){
  $u = git -C $r.FullName remote get-url origin 2>$null
  if($u){ $remotes[$r.Name] = $u }
}
foreach($n in 'SecondBrain'){
  $u = git -C "$U\Desktop\$n" remote get-url origin 2>$null; if($u){ $remotes[$n]=$u }
}
foreach($n in 'dotclaude'){ $remotes[$n] = 'https://github.com/erash11/dotclaude.git' }
foreach($k in $remotes.Keys){
  $target = Join-Path $cloneDir $k
  if(Test-Path $target){ Log "  CLONE $k : exists, fetching"; git -C $target fetch --all --prune 2>&1 | Out-Null }
  else { git clone --mirror $remotes[$k] $target 2>&1 | Out-Null; Log "  CLONE $k : $(if($LASTEXITCODE -eq 0){'OK'}else{'FAIL'})" }
}

# ---------- 5. Classification manifest ----------
$class | Export-Csv -Path (Join-Path $man 'classification.csv') -NoTypeInformation -Encoding UTF8
Log "MANIFEST classification.csv written ($($class.Count) entries)"

$total = ((Get-ChildItem $dest -Recurse -File -EA SilentlyContinue) | Measure-Object Length -Sum)
Log "TOTAL on SSD: $($total.Count) files, $([math]::Round($total.Sum/1GB,2)) GB"
Log "===== phase1-rescue end ====="

