input.command:
$log='D:\AssistantBackup\MANIFEST\rescue.log'
"=== orphan rescue (the structural hole) ==="
Select-String -Path $log -Pattern 'ORPHAN' | ForEach-Object { $_.Line }
"`n=== failures / errors ==="
$f = Select-String -Path $log -Pattern 'FAIL|ERR ' | ForEach-Object { $_.Line }
if($f){ $f } else { "none" }
"`n=== stage + totals ==="
