20	$StateFile = "$LogDir\backup-state.json"
21	$ErrorsLog = "$U\.claude\global-memory\transcripts\.errors.log"
22	$Errors = [System.Collections.Generic.List[string]]::new()
23	$Results = [System.Collections.Generic.List[object]]::new()
24	
25	New-Item -ItemType Directory -Force -Path $LogDir | Out-Null
26	
27	function Log($msg) {
28	    $line = "{0} {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
29	    Add-Content -Path $LogFile -Value $line
30	    Write-Output $line
31	}
32	
33	function Sync-Repo($path, $branch) {
34	    $name = Split-Path $path -Leaf
35	    if ($path -eq "$U\.claude") { $name = 'dotclaude' }
36	    if (-not (Test-Path (Join-Path $path '.git'))) { $Errors.Add("repo-missing:$name"); return }
37	    Push-Location $path
38	    try {
39	        git fetch origin 2>&1 | Out-Null
40	        $counts = git rev-list --left-right --count "origin/$branch...HEAD" 2>$null
41	        $behind = 0; $ahead = 0
42	        if ($counts) { $p = $counts -split '\s+'; $behind = [int]$p[0]; $ahead = [int]$p[1] }
43	        $dirty = (git status --porcelain | Measure-Object).Count
44	
45	        if ($behind -gt 0 -and ($ahead -gt 0 -or $dirty -gt 0)) {
46	            # Diverged with local changes: never merge blindly from automation.
47	            $Errors.Add("repo-diverged:$name")
48	            Log "REPO $name : DIVERGED (behind=$behind ahead=$ahead dirty=$dirty) - manual reconcile needed"
49	            return
50	        }
51	        if ($behind -gt 0) {
52	            if (-not $DryRun) { git pull --ff-only origin $branch 2>&1 | Out-Null }
53	            Log "REPO $name : fast-forwarded $behind commit(s)"
54	        }
55	        if ($dirty -gt 0) {
56	            if (-not $DryRun) {
57	                git add -A 2>&1 | Out-Null
58	                git commit -m ("chore: daily backup sync {0} [auto]" -f (Get-Date -Format 'yyyy-MM-dd')) 2>&1 | Out-Null
59	            }
60	            Log "REPO $name : committed $dirty change(s)"
61	        }
62	        $counts = git rev-list --left-right --count "origin/$branch...HEAD" 2>$null
63	        $ahead = if ($counts) { [int](($counts -split '\s+')[1]) } else { 0 }
64	        if ($DryRun -and $dirty -gt 0) { $ahead = 1 }
65	        if ($ahead -gt 0) {
66	            if (-not $DryRun) {
67	                git push origin $branch 2>&1 | Out-Null
68	                if ($LASTEXITCODE -ne 0) { $Errors.Add("repo-push:$name"); Log "REPO $name : PUSH FAILED"; return }
69	            }
70	            Log "REPO $name : pushed"
71	        }
72	        $Results.Add(@{ kind='repo'; name=$name; status='OK' })
73	    } finally { Pop-Location }
74	}
75	
76	function Snapshot($src, $dst, [string[]]$extraXD) {
77	    if (-not (Test-Path $src)) { Log "SNAP skip (missing): $src"; return }
78	    $xd = @('node_modules', '.venv', '__pycache__', '.git', 'cache', 'tmp') + $extraXD
79	    $args = @($src, $dst, '/MIR', '/R:2', '/W:5', '/NFL', '/NDL', '/NP', '/NJH') + ($xd | ForEach-Object { @('/XD', $_) })
80	    if ($DryRun) { $args += '/L' }
81	    robocopy @args | Select-Object -Last 6 | Add-Content -Path $LogFile
82	    if ($LASTEXITCODE -ge 8) {
83	        $Errors.Add("snapshot:$([IO.Path]::GetFileName($dst))")
84	        Log "SNAP $src -> $dst : FAILED (robocopy exit $LASTEXITCODE)"
85	    } else {
86	        Log "SNAP $src -> $dst : OK (exit $LASTEXITCODE)"
87	        $Results.Add(@{ kind='snapshot'; name=$dst; status='OK' })
88	    }
89	}
90	
91	Log "===== daily-backup start (DryRun=$DryRun) ====="
92	
93	# --- 1. Git memory repos ---
94	Sync-Repo "$U\Desktop\SecondBrain"      'main'
95	Sync-Repo "$U\.claude\global-memory"    'main'
96	Sync-Repo "$U\.claude"                  'main'
97	Sync-Repo "$U\.claude\skills"           'main'
98	
99	# --- 2a. Personal-context snapshots -> personal Google Drive (gmail) ---
100	# NOT OneDrive: the personal OneDrive account is not signed in on this machine
101	# (discovered 2026-07-23 — that folder is a dead local dir), and Google is the
102	# durable personal identity that survives any institutional change.
103	$P = 'G:\My Drive\Backups\Machine'
104	if (-not (Test-Path 'G:\My Drive')) {
105	    $Errors.Add('backup-target-offline:GoogleDrive')
106	    Log "TARGET G:\My Drive NOT MOUNTED - is Google Drive for Desktop running? Skipping personal snapshots."
107	}
108	Snapshot "$U\.claude\projects"  "$P\claude-projects"  @('worktrees')
109	Snapshot "$U\.codex\memories"   "$P\codex\memories"   @()
110	Snapshot "$U\.codex\sessions"   "$P\codex\sessions"   @()
111	Snapshot "$U\.codex\agents"     "$P\codex\agents"     @()
112	Snapshot "$U\.codex\sqlite"     "$P\codex\sqlite"     @()
113	Snapshot "$U\.gemini"           "$P\gemini"           @('antigravity_browser_profile')
114	
115	# --- 2b. Non-repo DEV folders -> Baylor OneDrive ---
116	$B = "$U\OneDrive - Baylor University\Backups\DEV-NonRepo"
117	Get-ChildItem "$U\Desktop\DEV" -Directory |
118	    Where-Object { -not (Test-Path (Join-Path $_.FullName '.git')) -and $_.Name -notmatch '^\.' } |
119	    ForEach-Object { Snapshot $_.FullName "$B\$($_.Name)" @('.playwright-mcp') }
120	
121	# --- 2c. Full memsearch reindex (no session-time cap) ---
122	# The SessionEnd hook indexes incrementally under a 45s cap - enough for normal
123	# session deltas, never for heavy days (a 41-chunk backlog on 7/24 needed >10 min
124	# at ONNX embedding speed). This nightly pass absorbs any backlog and resets the
125	# hook's consecutive-timeout alarm so mornings start clean.
126	$msExe = "$U\AppData\Roaming\Python\Python314\Scripts\memsearch.exe"
127	if (-not (Test-Path $msExe)) { $msExe = (Get-Command memsearch -ErrorAction SilentlyContinue).Source }
128	if ($msExe -and -not $DryRun) {
129	    $msFail = $false
130	    # Single source of truth: KeystoneOS declares the index set in
131	    # data\memory-index-paths.json (AGENTS.md routes "Memory index path templates"
132	    # there). This list used to be hardcoded here and had silently diverged from
133	    # that file - three declared paths (KeystoneOS project memory, Inbox\meetings,
134	    # .codex\memories) were never actually indexed by this nightly pass, so the
135	    # registry described an index that did not exist. Read it instead.
136	    $msPathsFallback = @(
137	        "$U\.claude\global-memory\transcripts",
138	        "$U\.claude\projects\C--Users-eric-rash\memory",
139	        "$U\.claude\claude-memory-compiler\daily",
140	        "$U\.claude\claude-memory-compiler\knowledge",
141	        "$U\Desktop\SecondBrain\Knowledge"
142	    )
143	    $msConfig = "$U\Desktop\DEV\KeystoneOS\data\memory-index-paths.json"
144	    $msPaths = $null
145	    if (Test-Path -LiteralPath $msConfig) {
146	        try {
147	            $declared = (Get-Content -Raw -LiteralPath $msConfig | ConvertFrom-Json).paths
148	            if ($declared -and $declared.Count -ge 1) {
149	                $msPaths = @($declared | ForEach-Object { ($_ -replace '\{HOME\}', $U) -replace '/', '\' })
150	                Log "INDEX path set: $($msPaths.Count) paths from memory-index-paths.json"
151	            }
152	        } catch { Log "INDEX config unreadable ($($_.Exception.Message)) - using built-in fallback list" }
153	    }
154	    if (-not $msPaths) {
155	        $msPaths = $msPathsFallback
156	        $Errors.Add('memsearch-index-config-missing')
157	        Log "INDEX path set: built-in fallback ($($msPaths.Count) paths) - memory-index-paths.json not usable"
158	    }
159	    # The backup's full reindex shares the SessionEnd hook's lock. Without this,
160	    # the nightly pass can run beside Claude/Codex hooks and multiply the Python
161	    # embedding workers. Reclaim only a dead owner; indexers can exceed 30s.
162	    $indexLockFile = "$U\.claude\global-memory\transcripts\.memsearch-index.lock"
163	    $indexLockStaleMs = 5 * 60 * 1000
164	    $haveIndexLock = $false
165	    try {
166	        $lockStream = [System.IO.File]::Open($indexLockFile, [System.IO.FileMode]::CreateNew)
167	        $lockStream.Close()
168	        [System.IO.File]::WriteAllText($indexLockFile, [string]$PID)
169	        $haveIndexLock = $true
170	    }
171	    catch {
172	        $ownerAlive = $false
173	        try {
174	            $ownerPid = [int](Get-Content -Raw -LiteralPath $indexLockFile)
175	            $null = Get-Process -Id $ownerPid -ErrorAction Stop
176	            $ownerAlive = $true
177	        } catch {}
178	        if (-not $ownerAlive) {
179	            $lockStale = $false
180	            try { $lockStale = (((Get-Date) - (Get-Item -LiteralPath $indexLockFile).LastWriteTime).TotalMilliseconds -ge $indexLockStaleMs) }
181	            catch { $lockStale = $true }
182	            if ($lockStale) {
183	                try {
184	                    Remove-Item -LiteralPath $indexLockFile -Force -ErrorAction Stop
185	                    $lockStream = [System.IO.File]::Open($indexLockFile, [System.IO.FileMode]::CreateNew)
186	                    $lockStream.Close()
187	                    [System.IO.File]::WriteAllText($indexLockFile, [string]$PID)
188	                    $haveIndexLock = $true
189	                } catch {}
190	            }
191	        }
192	    }
193	
194	    if (-not $haveIndexLock) {
195	        Log "INDEX skipped - another index run is active; next hook/nightly pass will catch up"
196	    }
197	    else {
198	        try {
199	            $existingPaths = @($msPaths | Where-Object { Test-Path $_ })
200	            if ($existingPaths.Count -gt 0) {
201	                $r = & $msExe index $existingPaths 2>&1 | Select-Object -Last 1
202	                Log "INDEX full set: $r"
203	                if ($LASTEXITCODE -ne 0) { $msFail = $true; $Errors.Add("memsearch-index:full-set") }
204	            }
205	        }
206	        finally {
207	            Remove-Item -LiteralPath $indexLockFile -Force -ErrorAction SilentlyContinue
208	        }
209	    }
210	    if (-not $msFail -and $haveIndexLock) {
211	        Remove-Item "$U\.claude\global-memory\transcripts\.memsearch-timeout-streak" -Force -ErrorAction SilentlyContinue
212	        Log "INDEX complete - hook timeout-streak counter reset"
213	    }
214	} elseif (-not $msExe) { $Errors.Add('memsearch-exe-missing'); Log "INDEX skipped: memsearch.exe not found" }
215	
216	# --- 2d. Mirror the recovery guide to the cloud backup root ---
217	if ((Test-Path 'G:\My Drive') -and (Test-Path "$U\.claude\RESTORE.md") -and -not $DryRun) {
218	    New-Item -ItemType Directory -Force -Path 'G:\My Drive\Backups' | Out-Null
219	    Copy-Item "$U\.claude\RESTORE.md" 'G:\My Drive\Backups\RESTORE.md' -Force
220	    Log "RESTORE.md mirrored to G:\My Drive\Backups\"
221	}
222	
223	# --- 3. State + escalation ---
224	$status = if ($Errors.Count -eq 0) { 'OK' } else { 'ERROR' }
225	@{
226	    lastRun  = (Get-Date -Format 'o')
227	    status   = $status
228	    errors   = @($Errors)
229	    okCount  = $Results.Count
230	    dryRun   = [bool]$DryRun
231	} | ConvertTo-Json | Set-Content -Path $StateFile
232	
233	if ($Errors.Count -gt 0 -and -not $DryRun) {
234	    $line = "[{0}] daily-backup: {1} error(s): {2} - see ~\.claude\scripts\logs\daily-backup.log" -f (Get-Date -Format 'yyyy-MM-dd HH:mm'), $Errors.Count, ($Errors -join ', ')
235	    Add-Content -Path $ErrorsLog -Value $line
236	}
237	
238	# Keep the log from growing unbounded.
239	if ((Get-Item $LogFile).Length -gt 2MB) {
240	    Get-Content $LogFile -Tail 2000 | Set-Content $LogFile
241	}
242	
243	Log "===== daily-backup end: $status ($($Errors.Count) errors) ====="
244	if ($Errors.Count -gt 0) { exit 1 } else { exit 0 }
245

