# Generates backup-manifest.json — the single authority on what gets backed up and where.
# Classification is a first pass requiring human review; institutional tagging is a
# judgment call, not a heuristic result.

$U = $env:USERPROFILE
$dev = "$U\Desktop\DEV"
$out = "$U\.claude\scripts\backup-manifest.json"

# Explicit classification. 'institutional' = contains athlete/roster/medical data held by
# Baylor. 'personal' = Eric's own IP, tooling, research, or career-durable work.
$institutional = @(
  'Football','ForcePlate_DecisionSystem','Risk_Stratification_Engine','DataBase_GPS_Reporting',
  'Catapult_API','AppliedUtilization','Ath_Medicine','AT_Utilization_Benchmarks','Baseball_JD',
  'Basketball','Basketball_Women','PlayerProfiles_FB_03-28-2026','PracticeIntensity',
  'Kinexon_Volleyball','AMS_Mini','SpecialRequests','Epilepsy-Baseball-Research',
  'Risk_Exposure_Windows','AI_Analyst','DexaProject','ValdReport','Program_Context_Meet',
  '_obsidian_extracted_from_FaceComps','agy'
)

$rows = New-Object System.Collections.Generic.List[object]

foreach($d in (Get-ChildItem $dev -Directory | Sort-Object Name)){
  if($d.Name -match '^\.') { continue }
  $isRepo = Test-Path (Join-Path $d.FullName '.git')
  $remote = if($isRepo){ (git -C $d.FullName remote get-url origin 2>$null) } else { $null }
  $cls = if($institutional -contains $d.Name){'institutional'}else{'personal'}

  # Destinations: SSD always (it is the only survivor-grade store). GitHub only where a
  # remote exists. Baylor OneDrive retained while access lasts, for institutional only.
  $dests = @('ssd')
  if($remote){ $dests += 'github' }
  if($cls -eq 'institutional'){ $dests += 'baylor' }

  $rows.Add([ordered]@{
    path         = "DEV/$($d.Name)"
    class        = $cls
    isRepo       = [bool]$isRepo
    remote       = $remote
    destinations = $dests
    captureOrphans = [bool]$isRepo      # untracked + ignored files git never pushes
    captureWorkingTree = [bool]$isRepo  # uncommitted edits to tracked files
  })
}

# ~/.claude subtrees
foreach($c in @(
  @{p='.claude/projects';              cls='personal'; d=@('ssd','drive')},
  @{p='.claude/global-memory';         cls='personal'; d=@('ssd','github')},
  @{p='.claude/skills';                cls='personal'; d=@('ssd','github')},
  @{p='.claude/claude-memory-compiler';cls='personal'; d=@('ssd','github')},
  @{p='.claude/agents';                cls='personal'; d=@('ssd','github')},
  @{p='.claude/hooks';                 cls='personal'; d=@('ssd','github')},
  @{p='.claude/scripts';               cls='personal'; d=@('ssd','github')},
  @{p='.codex';                        cls='personal'; d=@('ssd','drive')},
  @{p='.gemini';                       cls='personal'; d=@('ssd','drive')},
  @{p='Desktop/SecondBrain';           cls='personal'; d=@('ssd','github')}
)){
  $rows.Add([ordered]@{
    path=$c.p; class=$c.cls; isRepo=$false; remote=$null
    destinations=$c.d; captureOrphans=$false; captureWorkingTree=$false
  })
}

$manifest = [ordered]@{
  version   = 1
  generated = (Get-Date -Format 'yyyy-MM-dd')
  note      = 'Single authority for backup coverage. Default-deny: any DEV directory absent from paths[] fails the health check. Classification requires human review.'
  destinations = [ordered]@{
    ssd    = [ordered]@{ root='D:\AssistantBackup'; volumeLabel='CRASHBOX'; optional=$true;  note='Survivor-grade. Optional because the drive may be detached; absence warns, never fails silently.' }
    drive  = [ordered]@{ root='G:\My Drive\Backups\Machine'; optional=$false }
    baylor = [ordered]@{ root="$U\OneDrive - Baylor University\Backups\DEV-NonRepo"; optional=$true; deprecated=$true; note='Lost when Baylor access ends. Never the sole destination for anything.' }
    github = [ordered]@{ root='https://github.com/erash11'; optional=$false; note='Tracked files only. Never assume it covers gitignored data.' }
  }
  paths = $rows
}

$manifest | ConvertTo-Json -Depth 6 | Set-Content -Path $out -Encoding UTF8
"manifest written: $out"
"paths: $($rows.Count)  institutional: $(($rows|Where-Object{$_.class -eq 'institutional'}).Count)  personal: $(($rows|Where-Object{$_.class -eq 'personal'}).Count)"
"repos with orphan capture: $(($rows|Where-Object{$_.captureOrphans}).Count)"

